import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, texture, normalMap, displacementMap, mx_noiseFloat, mix, mul, add, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // STAGE: Create dark backdrop plane for context
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicMaterial({ color: '#0b0b10' });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // PARALLAX CARD: Tessellated plane with displacement mapping
  const cardGeo = new THREE.PlaneGeometry(1.8, 1.12, 64, 64);

  // Load image and depth textures
  Promise.all([
    ctx.textureLoader.loadTexture(config.imageUrl || '/prism-mock/home/nodes/parallax-stack.png'),
    ctx.textureLoader.loadTexture(config.depthMapUrl || '/prism-mock/home/nodes/parallax-stack.depth.png')
  ]).then(([imgTex, depthTex]) => {
    // Ensure textures are properly set
    imgTex.colorSpace = THREE.SRGBColorSpace;
    depthTex.colorSpace = THREE.LinearSRGBColorSpace;

    // TSL-based material with displacement
    const cardMat = new MeshStandardNodeMaterial({
      colorSpace: THREE.SRGBColorSpace
    });

    // Base color from image
    cardMat.colorNode = texture(imgTex, uv());

    // Displacement: subtle height variation (0.08 units max)
    const dispNode = mul(displacementMap(depthTex, uv()), 0.08);
    cardMat.displacementNode = dispNode;
    cardMat.displacementScale = 1.0;

    // Machined metal PBR: brushed anisotropy
    cardMat.roughness = 0.52;
    cardMat.metalness = 0.48;
    cardMat.clearcoat = 0.18;
    cardMat.clearcoatRoughness = 0.4;

    // Normal map for surface detail (reuse depth as pseudo-normal)
    cardMat.normalNode = normalMap(depthTex, uv(), mul(vec3(0.8), 2.0));

    const card = new THREE.Mesh(cardGeo, cardMat);
    card.position.set(0, 0, 0);
    group.add(card);

    // Lighting: key + rim for machined surface
    const keyLight = new THREE.DirectionalLight('#ffffff', 1.2);
    keyLight.position.set(0.6, 0.8, 1.0);
    group.add(keyLight);

    const rimLight = new THREE.DirectionalLight('#ff2a38', 0.65);
    rimLight.position.set(-0.8, 0.3, 0.7);
    group.add(rimLight);

    const ambientLight = new THREE.AmbientLight('#ffffff', 0.45);
    group.add(ambientLight);

    // Contact shadow plane (radial, subtle)
    const shadowGeo = new THREE.CircleGeometry(1.4, 32);
    const shadowMat = new THREE.MeshBasicMaterial({
      color: '#000000',
      opacity: 0.35,
      transparent: true
    });
    const shadow = new THREE.Mesh(shadowGeo, shadowMat);
    shadow.position.z = -0.05;
    shadow.rotation.x = Math.PI * 0.5;
    group.add(shadow);

    // State for interaction
    let isHovered = false;
    let baseY = 0;

    // Interaction handlers
    const handlers = {
      pointerenter: () => {
        if (isHovered) return;
        isHovered = true;
        gsap.to(card.position, {
          y: baseY + 0.15,
          duration: 0.6,
          ease: 'power3.out'
        });
        gsap.to(card.scale, {
          x: 1.02,
          y: 1.02,
          duration: 0.6,
          ease: 'power3.out'
        });
      },
      pointerleave: () => {
        isHovered = false;
        gsap.to(card.position, {
          y: baseY,
          duration: 0.5,
          ease: 'power2.out'
        });
        gsap.to(card.scale, {
          x: 1.0,
          y: 1.0,
          duration: 0.5,
          ease: 'power2.out'
        });
      },
      pointerdown: () => {
        gsap.to(card.scale, {
          x: 0.97,
          y: 0.97,
          duration: 0.12,
          ease: 'back.out'
        });
      },
      pointerup: () => {
        gsap.to(card.scale, {
          x: isHovered ? 1.02 : 1.0,
          y: isHovered ? 1.02 : 1.0,
          duration: 0.3,
          ease: 'power2.out'
        });
        ctx.emit('hub-features.select', { nodeId: config.id });
      }
    };

    card.userData.handlers = handlers;

    // Apply parallax-scroll primitive
    const parallaxResult = ctx.primitives['parallax-scroll'](card, {
      intensity: 0.25,
      trigger: 'scroll'
    });

    // Store for cleanup
    card.userData.parallaxResult = parallaxResult;
  });

  // Cleanup function
  group.userData.cleanup = function() {
    gsap.killTweensOf(group.children);
    group.children.forEach(child => {
      if (child.userData?.parallaxResult?.cleanup) {
        child.userData.parallaxResult.cleanup();
      }
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
    group.clear();
  };

  group.position.set(config.scenePosition?.[0] ?? -1.25, config.scenePosition?.[1] ?? 0.7, config.scenePosition?.[2] ?? 0);

  return group;
}
